package edu.pe.cibertec.saibm.membresia.infrastructure.migration;
import java.util.*;
public class MembershipBackfillReconciler {public MembershipReconciliationReport reconcile(List<MembershipBackfillPlan> source,List<Integer> targetPlans,List<MembershipBackfillAssignment> assignments,List<Integer> targetAssignments){var m=new ArrayList<String>();for(var p:source)if(!targetPlans.contains(p.legacyId()))m.add("missing plan "+p.legacyId());for(var a:assignments)if(!targetAssignments.contains(a.legacyUserId()))m.add("missing assignment "+a.legacyUserId());if(source.size()!=targetPlans.size())m.add("plan count mismatch");if(assignments.size()!=targetAssignments.size())m.add("assignment count mismatch");return new MembershipReconciliationReport(m.isEmpty(),source.size(),targetPlans.size(),assignments.size(),targetAssignments.size(),List.copyOf(m));}}
